#!/usr/bin/env bash
# qs-alias: cuarentena aceptar
# git-cuarentena.sh (git aliases: git cuarentena, git aceptar) - QUARANTINE-<task>, a quarantine
# for code generated by outside models (public or invented code only).
#   git cuarentena <task-branch>
#       creates '<node>/QUARANTINE-<task>' from the ORIGINAL of the task and checks it out.
#       Every commit made there must carry the 'Generated-by:' trailer and passes the strict gate
#       (the hooks check both). It is never integrated: 'git integra' refuses it.
#   git cuarentena --borrar <task-branch> [--yes]
#       deletes the quarantine (local and origin) and prints its tip to restore it.
#   git aceptar <commit>... --a <task-branch>
#       brings the commits of the quarantine of <task-branch> into the task, one commit each, as a
#       cherry-pick with the 'Reviewed-by: <user.name> <user.email>' trailer; 'Generated-by:'
#       stays. An unknown commit (not in the quarantine) or an unknown target is refused.
# Both refuse a repository whose .quality-rules.json has data_class "regulated". The alias name
# arrives in QS_ALIAS (see configure_repo), so one script serves both aliases.

# shellcheck disable=SC1091
if ! declare -F qs_policy_load >/dev/null 2>&1; then
	. "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/git-flow-lib.sh"
fi
if [ "${BASH_SOURCE[0]}" = "$0" ]; then set -euo pipefail; fi

# Print an error and exit.
# Arguments: $@ message. Returns: never (exit 1).
qr_die() {
	echo "[cuarentena] $*" >&2
	exit 1
}

# Refuse repositories whose data class is regulated and flows that have no special branches.
# Arguments: none. Returns: 0 when allowed; exits 1 with the reason otherwise.
qr_need_allowed() {
	local root rules
	root="$(git rev-parse --show-toplevel 2>/dev/null)" || qr_die "not inside a git repository"
	rules="$root/.quality-rules.json"
	if [ -f "$rules" ] && grep -Eiq '"data_class"[[:space:]]*:[[:space:]]*"regulated"' "$rules"; then
		qr_die "QUARANTINE is for public or invented code: this repository is regulated"
	fi
	if [ "${QS_BR_FLOW:-squash}" != squash ]; then
		qr_die "QUARANTINE needs branches.flow: squash (this repository keeps the 4.x merge flow)"
	fi
	special_enabled QUARANTINE || qr_die "QUARANTINE is not enabled in branches.special"
	return 0
}

# Check that a branch is an ordinary final task branch that exists, and set the globals of the
# task: QR_TASK (branch), QR_ORIG (its ORIGINAL) and QR_Q (the quarantine branch name).
# Arguments: $1 branch. Returns: 0; exits 1 with the reason otherwise.
# shellcheck disable=SC2034 # why: QR_* are read by the commands
qr_task() {
	local b="$1" node leaf
	[ -n "$b" ] || qr_die "name the task branch (for example 6.0.0/ot1/a)"
	valid_branch_name "$b" >/dev/null 2>&1 || qr_die "'$b' is not a valid branch name"
	[ -z "$(special_kind "$b")" ] || qr_die "'$b' is a special branch: name an ordinary task branch"
	! is_parent_branch "$b" || qr_die "'$b' is an ORIGINAL: name a final task branch"
	node="${b%/*}"
	leaf="${b##*/}"
	[ "$node" != "$b" ] || qr_die "'$b' is not a task branch"
	best_ref "$b" >/dev/null || qr_die "no such branch: $b"
	QR_TASK="$b"
	QR_ORIG="$(parent_branch "$b")"
	QR_Q="$node/QUARANTINE-$leaf"
	valid_branch_name "$QR_Q" >/dev/null 2>&1 || qr_die "'$QR_Q' is not a valid branch name"
	best_ref "$QR_ORIG" >/dev/null || qr_die "the ORIGINAL of $b does not exist: $QR_ORIG"
	return 0
}

# git cuarentena <task>: create and check out the quarantine of a task.
# Arguments: $1 task branch. Returns: 0 on success; exits 1 when the branch exists or the tree is dirty.
cmd_crear() {
	local base
	qr_task "${1:-}"
	! best_ref "$QR_Q" >/dev/null || qr_die "$QR_Q already exists"
	require_clean || exit 1
	base="$(best_ref "$QR_ORIG")"
	git switch -q -c "$QR_Q" --no-track "$base" || qr_die "cannot create $QR_Q"
	# why: phase 3 (autopublish) may not be in this checkout; without it the branch stays local
	if command -v qs_publish_new >/dev/null 2>&1; then qs_publish_new "$QR_Q" || true; fi
	echo "[cuarentena] created '$QR_Q' from $QR_ORIG (commits need 'Generated-by:'; 'git aceptar <commit> --a $QR_TASK' takes one in)"
}

# git cuarentena --borrar <task> [--yes]: delete the quarantine, local and origin.
# Arguments: $1 task branch, optional --yes (no question). Returns: 0; exits 1 when it does not
# exist, is checked out, or the answer is not yes.
cmd_borrar() {
	local yes=0 task="" a tip ans
	for a in "$@"; do
		if [ "$a" = --yes ]; then yes=1; else task="$a"; fi
	done
	qr_task "$task"
	best_ref "$QR_Q" >/dev/null || qr_die "no quarantine for $QR_TASK ($QR_Q)"
	[ "$(current_branch || true)" != "$QR_Q" ] || qr_die "$QR_Q is checked out: switch to another branch first"
	tip="$(git rev-parse -q --verify "refs/heads/$QR_Q" || git rev-parse -q --verify "refs/remotes/origin/$QR_Q")"
	if [ "$yes" != 1 ]; then
		printf '[cuarentena] delete %s (local and origin)? [y/N] ' "$QR_Q"
		read -r ans || ans=n
		case "$ans" in y | Y | yes) ;; *) qr_die "cancelled" ;; esac
	fi
	if git show-ref --verify -q "refs/heads/$QR_Q"; then git branch -D -q "$QR_Q"; fi
	if git rev-parse -q --verify "refs/remotes/origin/$QR_Q" >/dev/null; then
		git push -q origin --delete "$QR_Q" 2>/dev/null || echo "[cuarentena] WARN: could not delete origin/$QR_Q" >&2
		git update-ref -d "refs/remotes/origin/$QR_Q" 2>/dev/null || true
	fi
	echo "[cuarentena] deleted $QR_Q (tip $tip; restore with: git branch $QR_Q $tip)"
}

# The Reviewed-by value of the current user.
# Arguments: none. Returns: 0; prints 'name <email>'; exits 1 when user.name or user.email is unset.
qr_reviewer() {
	local n e
	n="$(git config user.name || true)"
	e="$(git config user.email || true)"
	[ -n "$n" ] && [ -n "$e" ] || qr_die "set user.name and user.email: the reviewer goes in 'Reviewed-by:'"
	printf '%s <%s>' "$n" "$e"
}

# Cherry-pick one commit into the checked out branch with the Reviewed-by trailer.
# Arguments: $1 commit sha, $2 reviewer. Returns: 0 on success; 1 when the pick conflicts or the
# commit is refused by the hooks (the work tree is restored).
qr_pick() {
	local c="$1" who="$2" msg
	msg="$(mktemp)"
	if ! git cherry-pick --no-commit "$c" >/dev/null 2>&1; then
		git cherry-pick --abort >/dev/null 2>&1 || git reset -q --hard HEAD
		rm -f "$msg"
		return 1
	fi
	git log -n1 --format=%B "$c" >"$msg"
	git interpret-trailers --in-place --if-exists addIfDifferent --trailer "Reviewed-by: $who" "$msg"
	if ! git commit -q -F "$msg" >/dev/null; then
		git reset -q --hard HEAD
		rm -f "$msg"
		return 1
	fi
	rm -f "$msg"
	return 0
}

# git aceptar <commit>... --a <task>: take quarantine commits into the task.
# Arguments: commits and '--a <task branch>'. Returns: 0 when all were taken; exits 1 on a refusal
# and 1 when a pick failed (earlier picks stay; the failing one leaves the task untouched).
cmd_aceptar() {
	local commits=() shas=() target="" who qref oref allowed c sha cur failed=0 a
	while [ $# -gt 0 ]; do
		a="$1"
		shift
		case "$a" in
		--a)
			target="${1:-}"
			shift || true
			;;
		-*) qr_die "unknown option: $a" ;;
		*) commits+=("$a") ;;
		esac
	done
	[ "${#commits[@]}" -gt 0 ] || qr_die "usage: git aceptar <commit>... --a <task-branch>"
	qr_task "$target"
	qref="$(best_ref "$QR_Q")" || qr_die "no quarantine for $QR_TASK: run 'git cuarentena $QR_TASK'"
	oref="$(best_ref "$QR_ORIG")"
	allowed="$(git rev-list "$oref..$qref")"
	for c in "${commits[@]}"; do
		sha="$(git rev-parse -q --verify "$c^{commit}" 2>/dev/null)" || qr_die "unknown commit: $c"
		grep -qx "$sha" <<<"$allowed" || qr_die "$c is not a commit of $QR_Q"
		shas+=("$sha")
	done
	who="$(qr_reviewer)"
	require_clean || exit 1
	git show-ref --verify -q "refs/heads/$QR_TASK" || qr_die "no local branch $QR_TASK"
	cur="$(current_branch || true)"
	if [ "$cur" != "$QR_TASK" ]; then
		if git worktree list --porcelain | grep -qx "branch refs/heads/$QR_TASK"; then
			qr_die "$QR_TASK is checked out in another worktree: switch there and run again"
		fi
		git switch -q "$QR_TASK" || qr_die "cannot switch to $QR_TASK"
	fi
	for sha in "${shas[@]}"; do
		if qr_pick "$sha" "$who"; then
			echo "[cuarentena] accepted ${sha:0:7} into $QR_TASK"
		else
			echo "[cuarentena] ${sha:0:7} failed (conflict or refused by the hooks); $QR_TASK untouched by it" >&2
			failed=1
			break
		fi
	done
	if [ -n "$cur" ] && [ "$cur" != "$QR_TASK" ]; then git switch -q "$cur"; fi
	[ "$failed" = 0 ]
}

# Entry point of the git aliases.
# Arguments: the command line after the alias. Returns: the status of the command.
qr_main() {
	qs_policy_load
	qr_need_allowed
	case "${QS_ALIAS:-cuarentena}" in
	aceptar) cmd_aceptar "$@" ;;
	*)
		case "${1:-}" in
		--borrar)
			shift
			cmd_borrar "$@"
			;;
		"" | -h | --help)
			awk 'NR > 3 && /^#/ { sub(/^# ?/, ""); print; next } NR > 3 { exit }' "${BASH_SOURCE[0]}"
			exit 2
			;;
		*) cmd_crear "$@" ;;
		esac
		;;
	esac
}

if [ "${BASH_SOURCE[0]}" = "$0" ]; then qr_main "$@"; fi
